+func TestFilesService_Add_RetriesSeekableBodyOnRateLimit(t *testing.T) {
+	t.Parallel()
+
+	contentType := "multipart/form-data; boundary=test"
+	payload := []byte("prebuilt multipart body")
+	var calls int
+	policy := pipedrive.RetryPolicy{
+		MaxAttempts:     2,
+		BaseDelay:       0,
+		RetryAllMethods: true,
+	}
+	client := newTestClientWithConfig(t, pipedrive.Config{RetryPolicy: &policy}, func(w http.ResponseWriter, r *http.Request) {
+		calls++
+		if r.Method != http.MethodPost {
+			t.Fatalf("unexpected method: %s", r.Method)
+		}
+		if r.URL.Path != "/files" {
+			t.Fatalf("unexpected path: %s", r.URL.Path)
+		}
+		if got := r.Header.Get("Content-Type"); got != contentType {
+			t.Fatalf("unexpected content type: %q", got)
+		}
+		body, err := io.ReadAll(r.Body)
+		if err != nil {
+			t.Fatalf("read body: %v", err)
+		}
+		if !bytes.Equal(body, payload) {
+			t.Fatalf("unexpected body: %q", body)
+		}
+
+		w.Header().Set("Content-Type", "application/json")
+		if calls == 1 {
+			w.WriteHeader(http.StatusTooManyRequests)
+			_, _ = w.Write([]byte(`{"error":"rate limited"}`))
+			return
+		}
+		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12,"name":"upload.txt"}}`))
+	})
+
+	path := t.TempDir() + "/upload.multipart"
+	if err := os.WriteFile(path, payload, 0o600); err != nil {
+		t.Fatalf("write temp file: %v", err)
+	}
+	body, err := os.Open(path)
+	if err != nil {
+		t.Fatalf("open temp file: %v", err)
+	}
+	defer body.Close()
+
+	file, err := client.Files.Add(context.Background(), body, contentType)
+	if err != nil {
+		t.Fatalf("Add error: %v", err)
+	}
+	if calls != 2 {
+		t.Fatalf("expected 2 calls, got %d", calls)
+	}
+	if file.ID != 12 || file.Name != "upload.txt" {
+		t.Fatalf("unexpected file: %#v", file)
+	}
+}
